static const char* G_SchemaSql =
	"CREATE TABLE IF NOT EXISTS content_item ("
	"id INTEGER PRIMARY KEY AUTOINCREMENT,"
	"title TEXT NOT NULL DEFAULT '',"
	"status INTEGER NOT NULL DEFAULT 0,"
	"payload_json TEXT NOT NULL DEFAULT '{}',"
	"category_id INTEGER NOT NULL DEFAULT 0,"
	"is_draft INTEGER NOT NULL DEFAULT 0,"
	"create_time INTEGER NOT NULL,"
	"update_time INTEGER NOT NULL DEFAULT 0,"
	"delete_time INTEGER NOT NULL DEFAULT 0"
	");"
	"CREATE INDEX IF NOT EXISTS idx_content_item_public ON content_item(delete_time, is_draft, status, update_time DESC);"
	"CREATE INDEX IF NOT EXISTS idx_content_item_admin ON content_item(delete_time, update_time DESC);"

	"CREATE TABLE IF NOT EXISTS comment_thread (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\ncomment_count INTEGER NOT NULL DEFAULT 0,\nvisible_count INTEGER NOT NULL DEFAULT 0,\nstatus INTEGER NOT NULL DEFAULT 1,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(content_id)\n);\nCREATE TABLE IF NOT EXISTS comment_item (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nthread_id INTEGER NOT NULL DEFAULT 0,\nparent_id INTEGER NOT NULL DEFAULT 0,\nauthor_name TEXT NOT NULL DEFAULT '',\nauthor_id TEXT NOT NULL DEFAULT '',\nbody TEXT NOT NULL DEFAULT '',\nip TEXT NOT NULL DEFAULT '',\nuser_agent TEXT NOT NULL DEFAULT '',\nstatus INTEGER NOT NULL DEFAULT 0,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\ndelete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS comment_audit_log (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncomment_id INTEGER NOT NULL DEFAULT 0,\naction TEXT NOT NULL DEFAULT '',\noperator_id TEXT NOT NULL DEFAULT '',\nnote TEXT NOT NULL DEFAULT '',\ncreate_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS comment_notification (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncomment_id INTEGER NOT NULL DEFAULT 0,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nevent TEXT NOT NULL DEFAULT '',\ntarget_type TEXT NOT NULL DEFAULT '',\ntarget_id TEXT NOT NULL DEFAULT '',\ntitle TEXT NOT NULL DEFAULT '',\nbody TEXT NOT NULL DEFAULT '',\nstatus INTEGER NOT NULL DEFAULT 0,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nread_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_comment_item_content ON comment_item(content_id, status, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_comment_item_audit ON comment_item(status, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_comment_audit_log_comment ON comment_audit_log(comment_id, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_comment_notification_status ON comment_notification(status, create_time DESC);\n"
	"CREATE TABLE IF NOT EXISTS tag (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nname TEXT NOT NULL DEFAULT '',\nslug TEXT NOT NULL DEFAULT '',\ndescription TEXT NOT NULL DEFAULT '',\nsort INTEGER NOT NULL DEFAULT 0,\nstatus INTEGER NOT NULL DEFAULT 1,\ncontent_count INTEGER NOT NULL DEFAULT 0,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\ndelete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS content_tag (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\ntag_id INTEGER NOT NULL DEFAULT 0,\nsort INTEGER NOT NULL DEFAULT 0,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(content_id, tag_id)\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_tag_slug ON tag(slug) WHERE delete_time = 0;\nCREATE INDEX IF NOT EXISTS idx_tag_status_sort ON tag(status, sort, id);\nCREATE INDEX IF NOT EXISTS idx_content_tag_tag ON content_tag(tag_id, sort, content_id);\n"
	"CREATE TABLE IF NOT EXISTS topic (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ntitle TEXT NOT NULL DEFAULT '',\nslug TEXT NOT NULL DEFAULT '',\nsummary TEXT NOT NULL DEFAULT '',\ncover TEXT NOT NULL DEFAULT '',\nsort INTEGER NOT NULL DEFAULT 0,\nstatus INTEGER NOT NULL DEFAULT 1,\ncontent_count INTEGER NOT NULL DEFAULT 0,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\ndelete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS topic_content (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ntopic_id INTEGER NOT NULL DEFAULT 0,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nsort INTEGER NOT NULL DEFAULT 0,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(topic_id, content_id)\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_topic_slug ON topic(slug) WHERE delete_time = 0;\nCREATE INDEX IF NOT EXISTS idx_topic_status_sort ON topic(status, sort, id);\nCREATE INDEX IF NOT EXISTS idx_topic_content_content ON topic_content(content_id, topic_id);\n"
	"CREATE TABLE IF NOT EXISTS sensitive_word (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nword TEXT NOT NULL DEFAULT '',\nlevel INTEGER NOT NULL DEFAULT 1,\nscope TEXT NOT NULL DEFAULT 'content',\ngroup_key TEXT NOT NULL DEFAULT 'default',\nreplacement TEXT NOT NULL DEFAULT '',\nstatus INTEGER NOT NULL DEFAULT 1,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\ndelete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS sensitive_hit_log (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ntarget_type TEXT NOT NULL DEFAULT '',\ntarget_id INTEGER NOT NULL DEFAULT 0,\nword_id INTEGER NOT NULL DEFAULT 0,\nword TEXT NOT NULL DEFAULT '',\nfield_name TEXT NOT NULL DEFAULT '',\naction TEXT NOT NULL DEFAULT '',\ncreate_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_sensitive_word_word_scope ON sensitive_word(word, scope) WHERE delete_time = 0;\nCREATE INDEX IF NOT EXISTS idx_sensitive_hit_target ON sensitive_hit_log(target_type, target_id, create_time DESC);\n"
	"CREATE TABLE IF NOT EXISTS static_rule (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nname TEXT NOT NULL DEFAULT '',\npath_pattern TEXT NOT NULL DEFAULT '',\ntemplate_name TEXT NOT NULL DEFAULT '',\nstatus INTEGER NOT NULL DEFAULT 1,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS static_task (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nrule_id INTEGER NOT NULL DEFAULT 0,\ntarget_type TEXT NOT NULL DEFAULT '',\ntarget_id INTEGER NOT NULL DEFAULT 0,\nstatus INTEGER NOT NULL DEFAULT 0,\nmessage TEXT NOT NULL DEFAULT '',\ncreate_time INTEGER NOT NULL DEFAULT 0,\nfinish_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS static_artifact (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nrule_id INTEGER NOT NULL DEFAULT 0,\ntarget_type TEXT NOT NULL DEFAULT '',\ntarget_id INTEGER NOT NULL DEFAULT 0,\npath TEXT NOT NULL DEFAULT '',\nhash TEXT NOT NULL DEFAULT '',\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(rule_id, target_type, target_id)\n);\nCREATE INDEX IF NOT EXISTS idx_static_task_status ON static_task(status, create_time);\nCREATE INDEX IF NOT EXISTS idx_static_artifact_path ON static_artifact(path);\n"
	"CREATE TABLE IF NOT EXISTS like_record (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nactor_id TEXT NOT NULL DEFAULT '',\nactor_key TEXT NOT NULL DEFAULT '',\nip TEXT NOT NULL DEFAULT '',\nstatus INTEGER NOT NULL DEFAULT 1,\ncreate_time INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(content_id, actor_key)\n);\nCREATE TABLE IF NOT EXISTS like_counter (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nlike_count INTEGER NOT NULL DEFAULT 0,\nupdate_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(content_id)\n);\nCREATE INDEX IF NOT EXISTS idx_like_record_content ON like_record(content_id, status, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_like_record_actor ON like_record(actor_key, content_id);\n"
	"CREATE TABLE IF NOT EXISTS view_counter (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nview_count INTEGER NOT NULL DEFAULT 0,\nunique_view_count INTEGER NOT NULL DEFAULT 0,\nlast_view_time INTEGER NOT NULL DEFAULT 0,\nUNIQUE(content_id)\n);\nCREATE TABLE IF NOT EXISTS view_log (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nvisitor_key TEXT NOT NULL DEFAULT '',\nip TEXT NOT NULL DEFAULT '',\nreferer TEXT NOT NULL DEFAULT '',\nuser_agent TEXT NOT NULL DEFAULT '',\ncreate_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS view_daily_stat (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\ncontent_id INTEGER NOT NULL DEFAULT 0,\nstat_date TEXT NOT NULL DEFAULT '',\nview_count INTEGER NOT NULL DEFAULT 0,\nunique_view_count INTEGER NOT NULL DEFAULT 0,\nUNIQUE(content_id, stat_date)\n);\nCREATE INDEX IF NOT EXISTS idx_view_log_content_time ON view_log(content_id, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_view_daily_date ON view_daily_stat(stat_date, view_count DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_seo_meta (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	seo_title TEXT NOT NULL DEFAULT '',\n	seo_keywords TEXT NOT NULL DEFAULT '',\n	seo_description TEXT NOT NULL DEFAULT '',\n	canonical TEXT NOT NULL DEFAULT '',\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_seo_meta_content ON content_seo_meta(content_id);\n"
	"CREATE TABLE IF NOT EXISTS content_slug_history (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	old_slug TEXT NOT NULL DEFAULT '',\n	new_slug TEXT NOT NULL DEFAULT '',\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_content_slug_history_old ON content_slug_history(old_slug, status, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_content_slug_history_content ON content_slug_history(content_id, create_time DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_redirect (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	source_path TEXT NOT NULL DEFAULT '',\n	target_url TEXT NOT NULL DEFAULT '',\n	status_code INTEGER NOT NULL DEFAULT 301,\n	hit_count INTEGER NOT NULL DEFAULT 0,\n	last_hit_time INTEGER NOT NULL DEFAULT 0,\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_redirect_source ON content_redirect(source_path) WHERE delete_time = 0;\nCREATE INDEX IF NOT EXISTS idx_content_redirect_status_source ON content_redirect(status, source_path, delete_time);\n"
	"CREATE TABLE IF NOT EXISTS content_category (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	parent_id INTEGER NOT NULL DEFAULT 0,\n	title TEXT NOT NULL DEFAULT '',\n	slug TEXT NOT NULL DEFAULT '',\n	description TEXT NOT NULL DEFAULT '',\n	cover_url TEXT NOT NULL DEFAULT '',\n	template_key TEXT NOT NULL DEFAULT '',\n	path TEXT NOT NULL DEFAULT '',\n	level INTEGER NOT NULL DEFAULT 0,\n	sort INTEGER NOT NULL DEFAULT 0,\n	status INTEGER NOT NULL DEFAULT 1,\n	seo_title TEXT NOT NULL DEFAULT '',\n	seo_keywords TEXT NOT NULL DEFAULT '',\n	seo_description TEXT NOT NULL DEFAULT '',\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_content_category_parent_sort ON content_category(parent_id, sort, id);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_category_parent_slug ON content_category(parent_id, slug) WHERE delete_time = 0;\n\nCREATE TABLE IF NOT EXISTS content_category_bind (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	category_id INTEGER NOT NULL DEFAULT 0,\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_category_bind_content ON content_category_bind(content_id) WHERE delete_time = 0;\nCREATE INDEX IF NOT EXISTS idx_content_category_bind_category ON content_category_bind(category_id, status, delete_time);\n"
	"CREATE TABLE IF NOT EXISTS content_media (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	attachment_xid TEXT NOT NULL DEFAULT '',\n	title TEXT NOT NULL DEFAULT '',\n	url TEXT NOT NULL DEFAULT '',\n	mime TEXT NOT NULL DEFAULT '',\n	ext TEXT NOT NULL DEFAULT '',\n	size INTEGER NOT NULL DEFAULT 0,\n	width INTEGER NOT NULL DEFAULT 0,\n	height INTEGER NOT NULL DEFAULT 0,\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_content_media_status ON content_media(status, delete_time, id);\n\nCREATE TABLE IF NOT EXISTS content_media_ref (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	media_id INTEGER NOT NULL DEFAULT 0,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	ref_type TEXT NOT NULL DEFAULT '',\n	create_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_media_ref_unique ON content_media_ref(media_id, content_id, ref_type);\nCREATE INDEX IF NOT EXISTS idx_content_media_ref_media ON content_media_ref(media_id);\nCREATE INDEX IF NOT EXISTS idx_content_media_ref_content ON content_media_ref(content_id);\n"
	"CREATE TABLE IF NOT EXISTS content_revision (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  content_id INTEGER NOT NULL DEFAULT 0,\n  revision_no INTEGER NOT NULL DEFAULT 0,\n  title TEXT NOT NULL DEFAULT '',\n  status INTEGER NOT NULL DEFAULT 0,\n  category_id INTEGER NOT NULL DEFAULT 0,\n  is_draft INTEGER NOT NULL DEFAULT 0,\n  payload_json TEXT NOT NULL DEFAULT '{}',\n  action TEXT NOT NULL DEFAULT '',\n  operator_id INTEGER NOT NULL DEFAULT 0,\n  create_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_revision_unique ON content_revision(content_id, revision_no);\nCREATE INDEX IF NOT EXISTS idx_content_revision_content ON content_revision(content_id, id DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_workflow_log (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  content_id INTEGER NOT NULL DEFAULT 0,\n  action TEXT NOT NULL DEFAULT '',\n  from_status INTEGER NOT NULL DEFAULT 0,\n  to_status INTEGER NOT NULL DEFAULT 0,\n  from_draft INTEGER NOT NULL DEFAULT 0,\n  to_draft INTEGER NOT NULL DEFAULT 0,\n  reason TEXT NOT NULL DEFAULT '',\n  operator_id INTEGER NOT NULL DEFAULT 0,\n  assignee_id INTEGER NOT NULL DEFAULT 0,\n  create_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_content_workflow_log_content ON content_workflow_log(content_id, id DESC);\nCREATE INDEX IF NOT EXISTS idx_content_workflow_log_action ON content_workflow_log(action, create_time DESC);\n\nCREATE TABLE IF NOT EXISTS content_workflow_notification (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  content_id INTEGER NOT NULL DEFAULT 0,\n  action TEXT NOT NULL DEFAULT '',\n  message TEXT NOT NULL DEFAULT '',\n  assignee_id INTEGER NOT NULL DEFAULT 0,\n  read_status INTEGER NOT NULL DEFAULT 0,\n  create_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_content_workflow_notification_assignee ON content_workflow_notification(assignee_id, read_status, id DESC);\nCREATE INDEX IF NOT EXISTS idx_content_workflow_notification_content ON content_workflow_notification(content_id, id DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_search_index (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  content_id INTEGER NOT NULL DEFAULT 0,\n  title TEXT NOT NULL DEFAULT '',\n  summary TEXT NOT NULL DEFAULT '',\n  body TEXT NOT NULL DEFAULT '',\n  keywords TEXT NOT NULL DEFAULT '',\n  status INTEGER NOT NULL DEFAULT 1,\n  update_time INTEGER NOT NULL DEFAULT 0\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_search_index_content ON content_search_index(content_id);\nCREATE INDEX IF NOT EXISTS idx_content_search_index_status ON content_search_index(status, update_time DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_sitemap_entry (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	loc TEXT NOT NULL DEFAULT '',\n	title TEXT NOT NULL DEFAULT '',\n	type TEXT NOT NULL DEFAULT 'content',\n	priority REAL NOT NULL DEFAULT 0.8,\n	changefreq TEXT NOT NULL DEFAULT 'weekly',\n	status INTEGER NOT NULL DEFAULT 1,\n	update_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_sitemap_entry_content_type ON content_sitemap_entry(content_id,type);\nCREATE INDEX IF NOT EXISTS idx_content_sitemap_entry_status_time ON content_sitemap_entry(status,update_time);\n"
	"CREATE TABLE IF NOT EXISTS content_related (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	source_content_id INTEGER NOT NULL DEFAULT 0,\n	related_content_id INTEGER NOT NULL DEFAULT 0,\n	relation_type TEXT NOT NULL DEFAULT 'manual',\n	weight INTEGER NOT NULL DEFAULT 0,\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_related_pair ON content_related(source_content_id,related_content_id,relation_type) WHERE delete_time=0;\nCREATE INDEX IF NOT EXISTS idx_content_related_source ON content_related(source_content_id,status,weight,update_time);\nCREATE INDEX IF NOT EXISTS idx_content_related_target ON content_related(related_content_id,status);\n"
	"CREATE TABLE IF NOT EXISTS content_form (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	form_key TEXT NOT NULL DEFAULT '',\n	title TEXT NOT NULL DEFAULT '',\n	schema_json TEXT NOT NULL DEFAULT '{}',\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_form_key ON content_form(form_key) WHERE delete_time=0;\nCREATE INDEX IF NOT EXISTS idx_content_form_content ON content_form(content_id,status,delete_time);\n\nCREATE TABLE IF NOT EXISTS content_form_submission (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	form_id INTEGER NOT NULL DEFAULT 0,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	data_json TEXT NOT NULL DEFAULT '{}',\n	ip TEXT NOT NULL DEFAULT '',\n	status INTEGER NOT NULL DEFAULT 1,\n	process_note TEXT NOT NULL DEFAULT '',\n	processed_by TEXT NOT NULL DEFAULT '',\n	process_time INTEGER NOT NULL DEFAULT 0,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_content_form_submission_form ON content_form_submission(form_id,create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_content_form_submission_content ON content_form_submission(content_id,create_time DESC);\n\nCREATE TABLE IF NOT EXISTS content_form_notification (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	submission_id INTEGER NOT NULL DEFAULT 0,\n	form_id INTEGER NOT NULL DEFAULT 0,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	event TEXT NOT NULL DEFAULT '',\n	title TEXT NOT NULL DEFAULT '',\n	body TEXT NOT NULL DEFAULT '',\n	status INTEGER NOT NULL DEFAULT 0,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	read_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_content_form_notification_submission ON content_form_notification(submission_id, id DESC);\nCREATE INDEX IF NOT EXISTS idx_content_form_notification_status ON content_form_notification(status, create_time DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_access_rule (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	content_id INTEGER NOT NULL DEFAULT 0,\n	access_mode TEXT NOT NULL DEFAULT 'public',\n	required_read_level INTEGER NOT NULL DEFAULT 0,\n	member_group_ids TEXT NOT NULL DEFAULT '',\n	password_hash TEXT NOT NULL DEFAULT '',\n	price INTEGER NOT NULL DEFAULT 0,\n	status INTEGER NOT NULL DEFAULT 1,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	update_time INTEGER NOT NULL DEFAULT 0,\n	delete_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_content_access_rule_content ON content_access_rule(content_id) WHERE delete_time=0;\nCREATE INDEX IF NOT EXISTS idx_content_access_rule_status ON content_access_rule(status,delete_time);\n"
	"CREATE TABLE IF NOT EXISTS content_audit_log (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	target_type TEXT NOT NULL DEFAULT 'content',\n	target_id INTEGER NOT NULL DEFAULT 0,\n	action TEXT NOT NULL DEFAULT '',\n	summary TEXT NOT NULL DEFAULT '',\n	detail_json TEXT NOT NULL DEFAULT '{}',\n	operator_type TEXT NOT NULL DEFAULT '',\n	operator_id INTEGER NOT NULL DEFAULT 0,\n	ip TEXT NOT NULL DEFAULT '',\n	create_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_content_audit_log_target ON content_audit_log(target_type, target_id, create_time DESC);\nCREATE INDEX IF NOT EXISTS idx_content_audit_log_action ON content_audit_log(action, create_time DESC);\n"
	"CREATE TABLE IF NOT EXISTS content_import_job (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	source_name TEXT NOT NULL DEFAULT '',\n	status TEXT NOT NULL DEFAULT 'preview',\n	total_count INTEGER NOT NULL DEFAULT 0,\n	success_count INTEGER NOT NULL DEFAULT 0,\n	fail_count INTEGER NOT NULL DEFAULT 0,\n	report_json TEXT NOT NULL DEFAULT '{}',\n	operator_id INTEGER NOT NULL DEFAULT 0,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	finish_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS content_export_job (\n	id INTEGER PRIMARY KEY AUTOINCREMENT,\n	export_type TEXT NOT NULL DEFAULT 'json',\n	status TEXT NOT NULL DEFAULT 'finished',\n	total_count INTEGER NOT NULL DEFAULT 0,\n	filter_json TEXT NOT NULL DEFAULT '{}',\n	result_json TEXT NOT NULL DEFAULT '{}',\n	operator_id INTEGER NOT NULL DEFAULT 0,\n	create_time INTEGER NOT NULL DEFAULT 0,\n	finish_time INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_content_import_job_time ON content_import_job(create_time DESC, id DESC);\nCREATE INDEX IF NOT EXISTS idx_content_export_job_time ON content_export_job(create_time DESC, id DESC);\n"
	;

