{
	const char* sValue;

	if ( (tblData == NULL) || (xvoType(tblData) != XVO_DT_TABLE) || Managed_IsBlank(sKey) ) {
		return "";
	}
	sValue = xvoTableGetText(tblData, sKey, (int)strlen(sKey));
	return sValue ? sValue : "";
}

