{
	const char* sValue;

	if ( (tblItem == NULL) || (xvoType(tblItem) != XVO_DT_TABLE) || Managed_IsBlank(sKey) ) {
		return "";
	}
	sValue = xvoTableGetText(tblItem, sKey, (int)strlen(sKey));
	return sValue ? sValue : "";
}

