	xvoTableSetInt(tblRow, "level", 5, sqlite3_column_int(stmt, 2));
	xvoTableSetText(tblRow, "scope", 5, (str)sqlite3_column_text(stmt, 3), 0, FALSE);
	xvoTableSetText(tblRow, "groupKey", 8, (str)sqlite3_column_text(stmt, 4), 0, FALSE);
